questionvariables.text:
/* Explicit list of 19 unique tuples for [m, x_pt] ensuring y_pt = m * x_pt <= 12 */
tuples : [
    [1, 3], [1, 4], [1, 5], [1, 6], [1, 7], [1, 8], [1, 9], [1, 10],
    [2, 2], [2, 3], [2, 4], [2, 5], [2, 6],
    [3, 2], [3, 3], [3, 4],
    [4, 2], [4, 3],
    [5, 2]
];
tup : rand(tuples);
m : tup[1];
x_pt : tup[2];
y_pt : m * x_pt;

/* Define target answers */
ta1 : 0;
ta2 : m;

/* The line is solid, and shaded below in the first quadrant. */
ta3 : y <= m*x;
ta3_wrong : y >= m*x;
